package nl.timtoys.corruptedadventure.registry;

import net.minecraft.core.registries.Registries;
import net.minecraft.resources.ResourceKey;
import net.minecraft.world.level.levelgen.carver.ConfiguredWorldCarver;
import nl.timtoys.corruptedadventure.CorruptedAdventure;

/**
 * Keys of the mod's configured carvers. The carvers themselves are datapack entries, generated by datagen.
 */
public final class ModConfiguredCarvers {
    // Ring 2 (change 26): vanilla's carvers, only deep. In vanilla's order.
    public static final ResourceKey<ConfiguredWorldCarver<?>> RING_2_CAVE = key("ring_2/cave");
    public static final ResourceKey<ConfiguredWorldCarver<?>> RING_2_CAVE_EXTRA_UNDERGROUND = key("ring_2/cave_extra_underground");
    public static final ResourceKey<ConfiguredWorldCarver<?>> RING_2_CANYON = key("ring_2/canyon");

    private ModConfiguredCarvers() {
    }

    private static ResourceKey<ConfiguredWorldCarver<?>> key(String path) {
        return ResourceKey.create(Registries.CONFIGURED_CARVER, CorruptedAdventure.id(path));
    }
}
